/** @jsxImportSource solid-js */
import { onMount, onCleanup, createEffect } from "solid-js";
import { mountPixelDissolveSlider, type PixelDissolveSliderOptions } from "../../components/pixel-dissolve-slider/PixelDissolveSliderEngine.js";
import type { MotionController } from "../../components/pixel-dissolve-slider/motion-runtime";

export function PixelDissolveSlider(props: { options?: PixelDissolveSliderOptions; class?: string }) {
  let host!: HTMLDivElement;
  let controller: MotionController | undefined;
  onMount(() => { controller = mountPixelDissolveSlider(host, props.options); });
  createEffect(() => { const options = props.options; controller?.update(options ?? {}); });
  onCleanup(() => controller?.destroy());
  return <div ref={host} class={props.class} data-motion-component="pixel-dissolve-slider" />;
}

